@staticmethod
def _prepare_query(query: str) -> str:
    """Strip a trailing semicolon so oracledb doesn't reject the statement.

    oracledb compiles a single SQL statement and treats a terminating
    semicolon as an invalid option, surfacing it as
    ``ORA-00922: missing or invalid option``. Removing the trailing
    semicolon lets statements like ``ALTER SESSION SET EDITION = V0;``
    run correctly.

    Anonymous PL/SQL blocks (``BEGIN`` / ``DECLARE`` / ``DO`` ...) carry
    their own terminating semicolon as part of the language syntax, so
    they are left untouched.
    """
    stripped = query.strip()
    upper = stripped.lstrip().upper()
    if upper.startswith(("BEGIN", "DECLARE", "DO")):
        return stripped
    return stripped.rstrip().rstrip(";").rstrip()

