class TestOracleAdapterTrailingSemicolon:
    """oracledb rejects a trailing semicolon with ORA-00922. See issue fix.

    Statements like ``ALTER SESSION SET EDITION = V0;`` must run even when the
    user (or the prompt) includes a terminating semicolon.
    """

    def _prepare(self, query: str) -> str:
        from sqlit.domains.connections.providers.oracle.adapter import OracleAdapter

        return OracleAdapter._prepare_query(query)

    def test_strips_trailing_semicolon(self):
        assert self._prepare("ALTER SESSION SET EDITION = V0;") == "ALTER SESSION SET EDITION = V0"

    def test_strips_trailing_whitespace_and_semicolon(self):
        assert self._prepare("  SELECT 1 FROM DUAL;  ") == "SELECT 1 FROM DUAL"

    def test_strips_multiple_trailing_semicolons(self):
        assert self._prepare("SELECT 1 FROM DUAL; ;") == "SELECT 1 FROM DUAL"

    def test_no_semicolon_unchanged(self):
        assert self._prepare("ALTER SESSION SET EDITION = V0") == "ALTER SESSION SET EDITION = V0"

    def test_plsql_block_keeps_terminating_semicolon(self):
        # Anonymous PL/SQL blocks carry their own semicolon as syntax.
        assert self._prepare("BEGIN dblog('x'); END;") == "BEGIN dblog('x'); END;"
        assert self._prepare("declare\n x int;\nbegin null; end;") == "declare\n x int;\nbegin null; end;"

    def test_execute_query_receives_stripped_statement(self):
        """Regression: a semicolonated statement reaches the driver without its ';'."""
        from sqlit.domains.connections.providers.oracle.adapter import OracleAdapter

        adapter = OracleAdapter()
        conn = MagicMock()
        cursor = conn.cursor.return_value

        def fake_execute(query, *args, **kwargs):
            if query.endswith(";"):
                raise Exception("ORA-00922: missing or invalid option")
            cursor.description = None
            cursor.rowcount = 1

        cursor.execute.side_effect = fake_execute

        # Should not raise ORA-00922
        adapter.execute_query(conn, "ALTER SESSION SET EDITION = V0;")
        adapter.execute_non_query(conn, "CREATE TABLE t (id int);")
        assert cursor.execute.call_args.args[0] == "CREATE TABLE t (id int)"


