#: Keyword containers that hold reusable subschemas addressable by root-relative $ref.
_ROOT_DEFINITION_KEYS: tuple[str, str] = ("$defs", "definitions")

def _has_root_relative_ref(self, node: Any) -> bool:
    """Return True if ``node`` contains any $ref that resolves against the root document."""
    if isinstance(node, dict):
        for key, value in node.items():
            if key == "$ref" and isinstance(value, str) and value.startswith("#"):
                return True
            if self._has_root_relative_ref(value):
                return True
    elif isinstance(node, list):
        return any(self._has_root_relative_ref(item) for item in node)
    return False

def _attach_root_definitions(self, schema: dict[str, Any]) -> dict[str, Any]:
    """Give a subschema access to the root's reusable definitions.

    A subschema (for example a single ``anyOf`` branch) is validated on its own,
    so root-relative references such as ``#/$defs/Item`` would otherwise resolve
    against an isolated document that lacks ``$defs``. When the subschema contains
    such references, copy the root schema's definition containers into a shallow
    copy so those references resolve against the original root scope.
    """
    if not self._has_root_relative_ref(schema):
        return schema
    attached = dict(schema)
    for defs_key in self._ROOT_DEFINITION_KEYS:
        if defs_key in attached:
            continue
        root_defs = self.root_schema.get(defs_key)
        if isinstance(root_defs, dict):
            attached[defs_key] = {
                key: self._prepare_schema_for_validation_node(value)
                for key, value in root_defs.items()
            }
    return attached

