def test_confirm_strips_ansi_when_color_disabled(runner):
    """``confirm`` should strip ANSI codes from the prompt when color output
    is disabled, matching how ``echo`` handles color. This is important for
    the test runner, which sets ``color=False`` by default.
    """

    @click.command()
    def cmd_confirm():
        click.confirm(click.style("Hello World!", fg="green"), abort=True)

    @click.command()
    def cmd_prompt():
        click.prompt(click.style("Name", fg="red"))

    # With color disabled, the ANSI codes are stripped from the prompt.
    assert (
        runner.invoke(cmd_confirm, input="Y", color=False).output
        == "Hello World! [y/N]: Y\n"
    )
    assert (
        runner.invoke(cmd_prompt, input="Bob", color=False).output == "Name: Bob\n"
    )

    # With color enabled, the ANSI codes are preserved.
    assert (
        runner.invoke(cmd_confirm, input="Y", color=True).output
        == "\x1b[32mHello World!\x1b[0m [y/N]: Y\n"
    )
    assert (
        runner.invoke(cmd_prompt, input="Bob", color=True).output
        == "\x1b[31mName\x1b[0m: Bob\n"
    )


